<script lang="ts">
 import { authClient } from '$lib/auth-client';import { invalidateAll } from '$app/navigation';import QRCode from 'qrcode';
 let {enabled,t}:{enabled:boolean;t:(key:string)=>string}=$props();let password=$state(''),code=$state(''),qr=$state(''),backups=$state<string[]>([]),message=$state(''),busy=$state(false);
 async function enable(){busy=true;try{const res=await authClient.twoFactor.enable({password});if(res.error){message=res.error.message??'Error';return;}if(res.data.method==='totp'){qr=await QRCode.toDataURL(res.data.totpURI);backups=res.data.backupCodes;}}finally{password='';busy=false;}}
 async function verify(){busy=true;try{const res=await authClient.twoFactor.verifyTotp({code});message=res.error?.message??t('saved');if(!res.error){qr='';code='';await invalidateAll();}}finally{busy=false;}}
</script>
<div class="card"><h2>{t('security')}</h2><p class="muted">{t('mfaRequired')}</p>{#if enabled}<p>✓ {t('active')}</p>{:else}<form onsubmit={(e)=>{e.preventDefault();enable();}}><label>{t('password')}<input type="password" bind:value={password} required autocomplete="current-password" /></label><button disabled={busy}>{t('enableMfa')}</button></form>{/if}{#if qr}<img src={qr} alt="Authenticator QR" width="200" height="200" /><form onsubmit={(e)=>{e.preventDefault();verify();}}><label>{t('totp')}<input bind:value={code} pattern="[0-9]{6}" inputmode="numeric" required autocomplete="one-time-code" /></label><button disabled={busy}>{t('verify')}</button></form>{/if}{#if backups.length}<p>{t('backup')}</p><pre>{backups.join('\n')}</pre><button onclick={()=>{backups=[];}}>{t('done')}</button>{/if}{#if message}<p role="status">{message}</p>{/if}</div>
<style>form{display:flex;gap:12px;align-items:end;margin:20px 0;flex-wrap:wrap}label{min-width:220px}pre{background:#f7f9f3;padding:18px;user-select:all}</style>
